(function(){'use strict';window.ALBORZ_KEY_COLLECTION={"1":[{"title":"احترام پیش از توضیح","explanation":"اولین جمله بهتر است تجربه و محدودیت مخاطب را ببیند، نه اینکه دفاع از عملکرد شعبه را آغاز کند.","example":"مدیر خرید با ناراحتی وارد می‌شود. رئیس شعبه می‌گوید: «می‌فهمم برای این جلسه زمان محدودی گذاشته‌اید؛ اولویت فوری شما کدام است؟»","transfer":"پیش از ارائه گزارش، چارچوب گفت‌وگو را با مخاطب هماهنگ کنید."},{"title":"شنیدن با حفظ بی‌طرفی","explanation":"بازتاب ناراحتی به معنای تأیید ادعای تقصیر یا قبول تعهد حقوقی نیست.","example":"مشتری می‌گوید: «شعبه عمداً کار را عقب انداخته.» پاسخ: «این برداشت برایتان جدی است؛ اجازه دهید مسیر پرونده را با هم مرور کنیم.»","transfer":"احساس را ببینید؛ نتیجه بررسی را پیش‌داوری نکنید."},{"title":"سؤال آغازینِ باز","explanation":"سؤال باز به طرف مقابل اجازه می‌دهد اولویت را تعریف کند؛ سؤال القایی گفت‌وگو را محدود می‌کند.","example":"به‌جای «مشکل شما فقط تأخیر است، درست است؟» بپرسید: «کدام بخش پیگیری بیش از همه کار شما را مختل کرده؟»","transfer":"اول مسئله را بفهمید و بعد راه‌حل بدهید."},{"title":"انتقال نرم به اصل موضوع","explanation":"تشریفات باید به شکل طبیعی به مسئله واقعی متصل شود؛ تعارف طولانی جای پاسخ‌گویی را نمی‌گیرد.","example":"پس از خوشامدگویی کوتاه: «اگر موافقید ابتدا وضعیت الحاقیه را روشن کنیم، بعد درباره گزینه‌های پیگیری تصمیم بگیریم.»","transfer":"از خوشامدگویی به توافق بر دستور جلسه برسید."}],"2":[{"title":"اقتدار بدون قطعیت نمایشی","explanation":"رهبر حرفه‌ای می‌تواند با آرامش بگوید چه چیزی قطعی و چه چیزی هنوز نیازمند بررسی است.","example":"مدیر منطقه عددی مغایر می‌پرسد؛ رئیس شعبه منابع دو گزارش را نام می‌برد و موعد تطبیق را اعلام می‌کند.","transfer":"ندانستنِ شفاف از پاسخ حدسی معتبرتر است."},{"title":"پاسخ‌گویی بدون مقصرسازی","explanation":"مسئولیت مدیریتی را می‌توان پذیرفت بی‌آنکه خطای فرد یا واحدی را پیش از بررسی قطعی دانست.","example":"در انتقاد از صف طولانی می‌گوید: «مدیریت ظرفیت با من است؛ علت را بررسی می‌کنیم و اقدام فوری را هم شروع می‌کنیم.»","transfer":"مسئولیت تصمیم با شماست، تشخیص علت نیاز به شواهد دارد."},{"title":"مکث حرفه‌ای","explanation":"مکث کوتاه فرصتی برای تفکیک واقعیت از واکنش احساسی است؛ نشانه ضعف یا تردید نیست.","example":"در پاسخ به پرسش تند مدیر ستادی، رئیس شعبه دو ثانیه مکث می‌کند و بعد سه واقعیت قابل اتکا را می‌گوید.","transfer":"سرعت پاسخ همیشه شاخص شایستگی نیست."},{"title":"هماهنگی کلام و حضور","explanation":"قاطعیت وقتی معتبر است که لحن، وضعیت بدن و محتوای پیام تناقض نداشته باشند.","example":"رئیس شعبه به‌جای بالا بردن صدا، صاف می‌نشیند و با آهنگ یکنواخت و جمله کوتاه مسیر اقدام را مشخص می‌کند.","transfer":"اقتدار با وضوح منتقل می‌شود، نه بلندی صدا."}],"3":[{"title":"معرفی نقش، نه صرفاً عنوان","explanation":"یک معرفی مؤثر روشن می‌کند هر فرد در تصمیم یا پاسخ تخصصی چه مسئولیتی دارد.","example":"در جلسه خسارت، رئیس شعبه توضیح می‌دهد چه کسی ارزیابی فنی می‌کند و چه کسی مسئول جمع‌بندی پاسخ است.","transfer":"عنوان سازمانی جای روشن‌سازی مسئولیت را نمی‌گیرد."},{"title":"اعتباربخشی به کارشناس","explanation":"مقام مدیریتی نباید تخصص افراد را تحت‌الشعاع قرار دهد؛ معرفی درست باعث شنیده‌شدن فرد متخصص می‌شود.","example":"در حضور مشتری بزرگ، از کارشناس می‌خواهد تفاوت پوشش‌ها را توضیح دهد و خود مسئول پیگیری تصمیم می‌ماند.","transfer":"واگذاری پاسخ تخصصی، انصراف از مسئولیت مدیریتی نیست."},{"title":"ترتیب معرفی زمینه‌مند","explanation":"رعایت احترام مهم است، اما ترتیب معرفی نباید افراد کلیدی برای تصمیم را نامرئی کند.","example":"در جلسه آنلاین، پس از معرفی کوتاه مدیران، نقش مسئول پاسخ فنی و ارتباطی را هم روشن می‌کند.","transfer":"هدف نهایی، شناخت نقش‌ها و تسهیل گفت‌وگوست."},{"title":"اصلاح اشتباه بی‌تحقیر","explanation":"اگر نام یا سمت کسی اشتباه گفته شد، اصلاح کوتاه و محترمانه بهتر از نادیده‌گرفتن یا توضیح طولانی است.","example":"«ببخشید، سمت خانم رضایی مسئول بررسی صدور است؛ از ایشان می‌خواهم این بخش را توضیح دهند.»","transfer":"اعتبار افراد را با اصلاح دقیق و بی‌حاشیه حفظ کنید."}],"4":[{"title":"میزبانی با مرز حرفه‌ای","explanation":"احترام و پذیرایی نباید دسترسی نامجاز به اطلاعات یا امتیاز خارج از رویه ایجاد کند.","example":"مهمان درخواست تصویر پرونده دارد؛ میزبان نمونه مجاز و بدون داده شخصی را نشان می‌دهد.","transfer":"مهمان‌نوازی به معنای تعلیق قواعد سازمان نیست."},{"title":"پیش‌بینی نیاز، نه تشریفات اضافی","explanation":"برای مهمان زمان، مسیر و امکان پیگیری مهم‌تر از مراسم طولانی است.","example":"پیش از ورود بازدیدکننده، اتاق، فایل‌های مجاز و مسئول پاسخ‌گویی آماده می‌شود.","transfer":"میزبانی مؤثر اصطکاک ملاقات را کم می‌کند."},{"title":"انعطاف در تغییر برنامه","explanation":"وقتی امکانات یا زمان تغییر می‌کند، توضیح شفاف همراه با پیشنهاد جایگزین اعتماد را حفظ می‌کند.","example":"پروژکتور قطع می‌شود؛ رئیس شعبه نمایش مجاز از لپ‌تاپ را پیشنهاد می‌دهد و زمان جلسه را دوباره توافق می‌کند.","transfer":"عذرخواهیِ صرف بدون راه جایگزین کافی نیست."},{"title":"پایان مهمان‌نوازی، آغاز پیگیری","explanation":"بدرقه محترمانه زمانی اثرگذار است که جمع‌بندی و مسئول پیگیری هم روشن باشد.","example":"پیش از خداحافظی، رئیس شعبه نام مسئول تهیه گزارش و زمان ارسال را اعلام می‌کند.","transfer":"تجربه مهمان با نتیجه پس از ملاقات کامل می‌شود."}],"5":[{"title":"نوبت برابر، مشارکت مؤثر","explanation":"توزیع فرصت صحبت به معنای زمان برابر مکانیکی نیست؛ باید صدای نقش‌های ضروری شنیده شود.","example":"در جلسه تمدید قرارداد، پس از مدیر فروش، کارشناس ریسک فرصت کوتاهی برای اعلام یک هشدار کلیدی پیدا می‌کند.","transfer":"به تناسب نقش و تصمیم نوبت بدهید."},{"title":"مدیریت دستور جلسه با اختیار مشترک","explanation":"انحراف فوری از برنامه گاهی درست است؛ اما تغییر مسیر باید آگاهانه و با موافقت گروه باشد.","example":"در میانه جلسه، ریسک جدیدی مطرح می‌شود؛ رئیس شعبه پیشنهاد می‌کند پنج دقیقه برای تعیین فوریت آن اختصاص دهند.","transfer":"کنترل جلسه یعنی تصمیم درباره اولویت، نه چسبیدن کور به برنامه."},{"title":"جمع‌بندی اختلاف، نه پنهان‌سازی آن","explanation":"وقتی توافق شکل نگرفته، ثبت شفاف اختلاف دیدگاه بهتر از اعلام توافق صوری است.","example":"دو واحد درباره موعد صدور اختلاف دارند؛ صورت‌جلسه دو دیدگاه و مرجع بررسی بعدی را تفکیک می‌کند.","transfer":"اختلاف روشن از توافق مبهم قابل‌مدیریت‌تر است."},{"title":"زمان‌بندیِ مبتنی بر خروجی","explanation":"زمانِ محدود را به تصمیم لازم و مسئول اقدام متصل کنید، نه فقط به تعداد اسلایدها.","example":"در پایان ده دقیقه، رئیس جلسه مشخص می‌کند کدام تصمیم گرفته شد و چه اطلاعاتی برای موضوع باز لازم است.","transfer":"زمان جلسه منابعی برای تصمیم است، نه صرفاً ارائه."}],"6":[{"title":"زبان بدن، نشانه نه حکم","explanation":"هیچ حرکت منفردی نیت، صداقت یا میزان همکاری را قطعی نشان نمی‌دهد.","example":"مشتری دوربین را نگاه نمی‌کند؛ رئیس شعبه با یک پرسش روشن‌ساز میزان درک موضوع را می‌سنجد.","transfer":"نشانه‌ها را در متن موقعیت و فرد تفسیر کنید."},{"title":"لحن متناسب با فوریت","explanation":"آرام‌بودن با بی‌تفاوت‌بودن فرق دارد؛ فوریت باید در وضوح و اقدام دیده شود، نه شدت صدا.","example":"در تماس درباره خسارت فوری، رئیس شعبه شمرده صحبت می‌کند و اقدام و موعد تماس بعدی را دقیق می‌گوید.","transfer":"فوریت را با تعهد مشخص بیان کنید."},{"title":"مکث برای شنیدن","explanation":"سکوت کوتاه پس از اعتراض به طرف مقابل فرصت توضیح می‌دهد، اگر با توجه و پرسش همراه باشد.","example":"بعد از شکایت مشتری دو ثانیه مکث می‌کند، سپس می‌پرسد: «کدام قسمت بیشترین نگرانی را ایجاد کرده؟»","transfer":"مکث زمانی مفید است که راه فهم بیشتر را باز کند."},{"title":"هماهنگی صدا، چهره و پیام","explanation":"جمله همدلانه با چهره تحقیرآمیز یا لحن شتاب‌زده اثر خود را از دست می‌دهد.","example":"رئیس شعبه هنگام بیان محدودیت، به‌جای لبخند نامتناسب، حالت جدی اما محترمانه حفظ می‌کند.","transfer":"کلام و رفتار غیرکلامی باید همسو باشند."}],"7":[{"title":"قاطعیت با راه جایگزین","explanation":"رد یک درخواست خارج از اختیار باید همراه با دلیل کوتاه و مسیر مجاز بعدی باشد.","example":"بیمه‌گذار تأیید فوری می‌خواهد؛ مدیر می‌گوید: «قبل از بررسی نمی‌توانم تأیید کنم؛ الان مدارک و مسئول رسیدگی را روشن می‌کنیم.»","transfer":"نه گفتنِ سازنده بن‌بست ایجاد نمی‌کند."},{"title":"مرز تعهد و امیدواری","explanation":"عبارت امیدوارکننده نباید در ذهن مشتری به تضمین نتیجه تبدیل شود.","example":"به‌جای «تقریباً قطعی است»، می‌گوید: «پرونده در مرحله بررسی است؛ موعد اعلام وضعیت فردا خواهد بود.»","transfer":"زمان پیگیری را وعده بدهید، نه نتیجه نامعلوم را."},{"title":"شفافیت بدون خشونت کلامی","explanation":"بیان روشن محدودیت نیازی به سرزنش مشتری یا نمایش قدرت ندارد.","example":"در برابر اصرار برای تغییر نوبت می‌گوید: «اولویت‌ها بر اساس ضابطه بررسی می‌شود؛ وضعیت پرونده شما را امروز اطلاع می‌دهیم.»","transfer":"قاطعیت از ثبات معیار می‌آید، نه تهدید."},{"title":"پرسش قبل از مخالفت","explanation":"درخواست نامناسب ممکن است پشت خود یک نیاز مشروع پنهان داشته باشد؛ ابتدا نیاز را شناسایی کنید.","example":"مشتری می‌خواهد سندی خارج از روال دریافت کند؛ رئیس شعبه می‌پرسد برای چه تصمیم و تا چه زمانی به اطلاعات نیاز دارد.","transfer":"نیاز را تأیید کنید، نه الزاماً راه درخواستی را."}],"8":[{"title":"کرامت مراجعه‌کننده اولویت دارد","explanation":"در بحران، حفظ تصویر سازمان نباید رسیدگی واقعی به فرد آسیب‌دیده را به حاشیه ببرد.","example":"هم‌زمان با بازدید رسمی، فردی در صف نیاز به رسیدگی فوری دارد؛ مسئول مشخصی برای کمک تعیین می‌شود.","transfer":"مسئله را مدیریت کنید، نه صرفاً از دید مهمان دور کنید."},{"title":"تفکیک اقدام فوری از ریشه‌یابی","explanation":"در اختلال عملیاتی، برای رفع فشار لحظه‌ای اقدام کنید و بررسی علت را با داده ادامه دهید.","example":"سامانه نوبت‌دهی می‌افتد؛ مسیر موقت مجاز اعلام می‌شود و بررسی فنی جدا ادامه می‌یابد.","transfer":"حل موقت و پیشگیری بلندمدت دو کار متفاوت‌اند."},{"title":"تفویض روشن و قابل پیگیری","explanation":"دستور کلی «رسیدگی کنید» در شلوغی کافی نیست؛ کار باید صاحب و زمان داشته باشد.","example":"یک همکار اطلاع‌رسانی به منتظران و همکار دیگر پیگیری سامانه را به عهده می‌گیرد.","transfer":"در بحران، نقش مشخص از دستور کلی مؤثرتر است."},{"title":"پاسخ کوتاه و غیر‌دفاعی","explanation":"توضیح طولانی درباره مقصرها معمولاً اعتراض را حل نمی‌کند؛ ابتدا نیاز و اقدام روشن شود.","example":"در برابر اعتراض عمومی: «انتظار شما طولانی شده؛ الان وضعیت صف را اعلام و اولویت‌های فوری را بررسی می‌کنیم.»","transfer":"مسئولانه بگویید چه می‌کنید، نه چه کسی مقصر است."}],"9":[{"title":"تفاوت نقش‌ها، تفاوت پاسخ‌ها","explanation":"انصاف در ارتباط به معنای ارائه اطلاعات یکسان نیست؛ پاسخ باید متناسب با نقش و مجوز باشد.","example":"مدیر مالی خلاصه تعهد، نماینده وضعیت پیگیری و کارشناس مدرک فنی می‌گیرد؛ هرکدام در کانال مجاز.","transfer":"تناسب اطلاعات از یکسان‌سازی مهم‌تر است."},{"title":"مدیریت انتظارات متعارض","explanation":"پیش از ارائه راه‌حل مشترک، روشن کنید هر ذی‌نفع دقیقاً چه نتیجه‌ای می‌خواهد.","example":"نماینده سرعت را می‌خواهد و مدیر مالی مستندات؛ رئیس شعبه برای هر دو خروجی و موعد متفاوت توافق می‌کند.","transfer":"نیاز مشترک را کشف کنید، تفاوت‌ها را پنهان نکنید."},{"title":"بی‌طرفی در تعارض نقش‌ها","explanation":"نزدیکی رابطه یا جایگاه فرد نباید معیار اولویت خلاف ضابطه باشد.","example":"مشتری بزرگ درخواست تقدم دارد؛ معیار فوریت و رویه بررسی برای همه یکسان توضیح داده می‌شود.","transfer":"احترام متفاوت از امتیاز بدون مبناست."},{"title":"کانال درست انتقال اطلاعات","explanation":"سریع‌ترین کانال لزوماً امن‌ترین یا مجازترین نیست؛ نیاز به هماهنگی و محرمانگی هم‌زمان وجود دارد.","example":"نماینده درخواست تصویر پرونده در پیام‌رسان شخصی می‌کند؛ مسیر رسمی امن جایگزین پیشنهاد می‌شود.","transfer":"سرعت باید در چارچوب دسترسی مجاز باشد."}],"10":[{"title":"تفکیک تصمیم از موضوع باز","explanation":"در پایان جلسه لازم است روشن شود چه چیزی توافق شده و چه چیزی هنوز در دست بررسی است.","example":"صورت‌جلسه در دو بخش «توافق‌شده» و «نیازمند تأیید تخصصی» تنظیم می‌شود.","transfer":"جمع‌بندی خوش‌بینانه جای شفافیت را نمی‌گیرد."},{"title":"مسئول و موعدِ مشخص","explanation":"عبارت «پیگیری می‌شود» بدون صاحب کار و زمان خبر بعدی قابل اتکا نیست.","example":"برای مدارک باقیمانده، واحد مسئول و تاریخ اعلام وضعیت در صورت‌جلسه درج می‌شود.","transfer":"تعهد قابل سنجش به فرد، اقدام و زمان نیاز دارد."},{"title":"اطمینان از برداشت مشترک","explanation":"پرسش «همه موافق‌اند؟» الزاماً سوءبرداشت را آشکار نمی‌کند؛ بازگویی توافق دقیق‌تر است.","example":"رئیس شعبه می‌گوید: «برداشت من این است که پوشش هنوز تأیید نشده؛ آیا همین را در جمع‌بندی ثبت کنیم؟»","transfer":"فهم مشترک را با بازگویی و اصلاح بررسی کنید."},{"title":"پیگیری، بخشی از تجربه ارتباطی","explanation":"کیفیت پایان ملاقات به انجام قول اطلاع‌رسانی وابسته است، نه فقط بدرقه محترمانه.","example":"حتی وقتی نتیجه بررسی آماده نیست، در موعد مقرر وضعیت واقعی به گیرندگان مجاز گزارش می‌شود.","transfer":"عدم قطعیت را می‌توان با اطلاع‌رسانی قابل پیش‌بینی مدیریت کرد."}]};window.ALBORZ_KEY_COLLECTION_READY=true;})();
